#include "cryptoutils.h"
int main(void){long double log2fact=0;for(int i=2;i<=25;i++)log2fact+=log2l((long double)i);printf("Playfair has 25 cells because I/J share one cell.\n");printf("Raw keyspace: 25! permutations.\nlog2(25!) = %.4Lf, so 25! is approximately 2^%.1Lf.\n",log2fact,log2fact);printf("If global cyclic row/column translations are treated as equivalent (25 layouts per equivalence class), effective count is 25!/25 = 24!.\n");printf("log2(24!) = %.4Lf, so the adjusted count is approximately 2^%.1Lf.\n",log2fact-log2l(25.0L),log2fact-log2l(25.0L));puts("The equivalence assumption is stated explicitly because textbook treatments may count equivalent squares differently.");return 0;}
